
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_br89_explicit_1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_br89_explicit_1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.417183422474206e+00, -3.405262631017657e+00, -3.383363278552896e+00, -3.343432524556882e+00, -3.272052605523193e+00, -3.148573640761989e+00, -2.945273454487375e+00, -2.635593014019827e+00, -2.218120664898156e+00, -1.730698392451462e+00, -1.206312067567762e+00, -7.109525624445869e-01, -5.669162702703604e-01, -4.988224267535664e-01, -3.941541492978431e-01, -2.740720335572827e-01, -1.787238421536767e-01, -1.166460946814898e-01, -7.694705232562586e-02, -5.169931455068686e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


